using JobOrbit.Application.Auditing;using JobOrbit.Application.DTOs.AdminAuditLogs;using JobOrbit.Application.Interfaces;
namespace JobOrbit.Application.Services;public sealed class AdminAuditLogService(IAdminAuditLogRepository repo):IAdminAuditLogService{public Task<AdminAuditLogListResult>ListAsync(AdminAuditLogQuery q,CancellationToken t=default){q.Page=Math.Max(1,q.Page);q.PageSize=Math.Clamp(q.PageSize,1,100);return repo.ListAsync(q,t);}public Task<AdminAuditLogDetailsDto?>DetailsAsync(int id,CancellationToken t=default)=>repo.DetailsAsync(id,t);public IReadOnlyList<AuditLogActionLookupDto>Actions()=>AuditCatalog.Actions.OrderBy(x=>x.Value.Category).ThenBy(x=>x.Value.Label).Select(x=>new AuditLogActionLookupDto(x.Key,x.Value.Label,x.Value.Category)).ToList();public IReadOnlyList<AuditLogEntityTypeLookupDto>EntityTypes()=>AuditCatalog.EntityTypes.OrderBy(x=>x.Value).Select(x=>new AuditLogEntityTypeLookupDto(x.Key,x.Value)).ToList();}
